@startuml

class SensorController {
}

class Apartment {
  +address : string
  +emailAddress : string
}

class Inhabitant {
  +username : string
  +password : string
}

class Room {
  +description : string
}

class Sensor {
  +vendorId : string
  +description : string
  +unit : Unit
  +threshold : float
}

abstract class MeasuredValue {
  +timestamp : datetime
  +value : float
}

class LastValue {
  +value : float
}

abstract class TemperatureSensor extends Sensor {
  +min : float
  +max : float
}

class PowerSensor extends Sensor {
  +counterReading : float
}

class EMonitor {
}

enum Unit {
  CELSIUS
  WATT
}

SensorController "1" -- "1" Apartment : manages
Apartment "1" *-- "2..*" Room : consists of
Apartment "1" -- "*" Inhabitant : has
Inhabitant "0..1" -- "*" Sensor : configures
Sensor "1" -- "1" Room : is assigned to
Sensor "1" *-- "*" MeasuredValue : records
Sensor "1" -- "0..1" LastValue : provides
Sensor "*" -- "1" SensorController : reports to
EMonitor ..> Sensor : checks thresholds
EMonitor ..> Apartment : sends alerts to

@enduml

